/**
 * Auto-generated AI Agent Modeling Skills.
 * Generated from markdown files located in the root /skills directory.
 * Do not edit this file directly; edit markdown files in /skills or run 'npm run sync:skills'.
 */
import { AIAgentSkillDefinition } from './types';

declare const require: any;
declare const __dirname: string;
declare const process: any;

/**
 * Parses a markdown string with optional YAML frontmatter into an AIAgentSkillDefinition.
 */
export function parseSkillMarkdown(content: string, fallbackId: string = 'skill'): AIAgentSkillDefinition {
  let id = fallbackId;
  let name = fallbackId;
  let description = '';
  let enabled = true;
  let body = content;

  const fmMatch = content.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
  if (fmMatch) {
    const yamlBlock = fmMatch[1];
    body = fmMatch[2].trim();

    const lines = yamlBlock.split(/\r?\n/);
    for (const line of lines) {
      const match = line.match(/^([a-zA-Z0-9_-]+)\s*:\s*(.*)$/);
      if (match) {
        const key = match[1].trim().toLowerCase();
        let val = match[2].trim();
        if ((val.startsWith('"') && val.endsWith('"')) || (val.startsWith("'") && val.endsWith("'"))) {
          val = val.slice(1, -1);
        }
        if (key === 'id') id = val;
        else if (key === 'name') name = val;
        else if (key === 'description') description = val;
        else if (key === 'enabled') enabled = val !== 'false';
      }
    }
  }

  if (name === fallbackId) {
    const headingMatch = body.match(/^#\s+(.+)$/m);
    if (headingMatch) {
      name = headingMatch[1].trim();
    }
  }

  if (!description) {
    const bodyWithoutHeading = body.replace(/^#\s+[^\r\n]+(?:\r?\n)*/, '').trim();
    const paragraphs = bodyWithoutHeading
      .split(/\r?\n\r?\n/)
      .map((p) => p.trim())
      .filter((p) => p && !p.startsWith('#'));
    if (paragraphs.length > 0) {
      description = paragraphs[0].replace(/\r?\n/g, ' ').slice(0, 180);
    }
  }

  return {
    id,
    name,
    description,
    instructions: body,
    enabled,
  };
}

